// Extrair dados do webhook
const wh = $input.first().json;
const body = (wh.resume_id !== undefined) ? wh : (wh.body || wh);

const resumeId   = body.resume_id;
const callbackUrl = body.callback_url;
const cvText     = String(body.cv_text || '').slice(0, 6000);

if (!resumeId || !callbackUrl) {
  throw new Error('Dados em falta: resume_id=' + resumeId + ' callback_url=' + callbackUrl);
}

// Construir prompt
const prompt =
  'Analisa o seguinte curriculo e responde APENAS com JSON valido com estes campos: ' +
  'score (inteiro 0-100), skills (lista de strings), summary (string), experience (string), ' +
  'education (string), languages (string), feedback (string).\n\nCurriculo:\n' + cvText;

// Chamar Ollama — stream tem de ser boolean false, nunca string
const ollamaResp = await $helpers.httpRequest({
  method: 'POST',
  url: 'http://127.0.0.1:11434/api/generate',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ model: 'llama3.2:1b', stream: false, format: 'json', prompt }),
  returnFullResponse: false
});

function toStr(val) {
  if (val == null) return '';
  if (typeof val === 'string') return val.trim();
  if (Array.isArray(val)) return val.map(i => (typeof i === 'object' ? JSON.stringify(i) : String(i))).join(', ');
  if (typeof val === 'object') return Object.values(val).filter(Boolean).join(' | ') || JSON.stringify(val);
  return String(val);
}

let analysis = {};
try {
  const raw = String(
    (typeof ollamaResp === 'string' ? ollamaResp : null) ||
    (ollamaResp && ollamaResp.response) ||
    '{}'
  );
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch (_) {
  analysis = {};
}

const score      = Math.min(100, Math.max(0, parseFloat(analysis.score) || 50));
const skills     = Array.isArray(analysis.skills)
  ? analysis.skills.map(s => (typeof s === 'object' ? toStr(s) : String(s))).join(', ')
  : toStr(analysis.skills) || 'Nao identificadas';
const summary    = toStr(analysis.summary)    || 'Resumo nao disponivel';
const experience = toStr(analysis.experience) || 'Nao especificada';
const education  = toStr(analysis.education)  || 'Nao especificada';
const languages  = toStr(analysis.languages)  || 'Nao identificados';
const feedback   = toStr(analysis.feedback)   || 'Analise concluida.';

// Callback para o Django
await $helpers.httpRequest({
  method: 'POST',
  url: callbackUrl,
  headers: {
    'Content-Type': 'application/json',
    'X-Kubuka-Secret': 'kubuka-secret-token-2025'
  },
  body: JSON.stringify({ score, skills, summary, experience, education, languages, feedback }),
  returnFullResponse: false
});

return [{ json: { success: true, resume_id: resumeId, score } }];
